import{_ as o,y as a,a as n,o as u,ag as r,D as t,I as l,g as i}from"./chunks/framework.C2qfZH9T.js";const A=JSON.parse('{"title":"Autorisations basées sur les rôles","description":"","frontmatter":{},"headers":[],"relativePath":"b2b-ecommerce-platform/role-based-permissions.md","filePath":"b2b-ecommerce-platform/role-based-permissions.md","lastUpdated":1782937842000}'),p={name:"b2b-ecommerce-platform/role-based-permissions.md"};function m(d,e,c,g,f,_){const s=a("ImagePopup");return u(),n("div",null,[e[0]||(e[0]=r('<h1 id="autorisations-basees-sur-les-roles" tabindex="-1">Autorisations basées sur les rôles <a class="header-anchor" href="#autorisations-basees-sur-les-roles" aria-label="Permalink to &quot;Autorisations basées sur les rôles&quot;">​</a></h1><p>La fonctionnalité Autorisations basées sur les rôles permet aux entreprises de créer des rôles personnalisés et de définir ce à quoi chaque utilisateur peut accéder au sein de l&#39;organisation.</p><p>Cela permet de garantir que chaque utilisateur a uniquement accès aux fonctionnalités pertinentes pour ses responsabilités.</p><h3 id="etapes-pour-creer-un-role" tabindex="-1">Étapes pour créer un rôle <a class="header-anchor" href="#etapes-pour-creer-un-role" aria-label="Permalink to &quot;Étapes pour créer un rôle&quot;">​</a></h3><p><strong>Étape : 1</strong> Accédez à Mon <strong>Compte → Profil → Rôles</strong> depuis la vitrine de l&#39;entreprise.</p><p>La page <strong>Rôles dans l&#39;entreprise</strong> apparaîtra, affichant tous les rôles existants avec des options pour les rechercher, les filtrer ou les gérer.</p><p>Comme le montre l&#39;image ci-dessous, vous pouvez afficher la liste des rôles existants, tels que « Administrateur ».</p>',7)),t(s,{src:"/images/b2b-ecommerce-platform/1-company-roles.png",alt:"Super Admin Login"}),e[1]||(e[1]=r(" <p><strong>Étape : 2</strong> Cliquez sur Ajouter un rôle pour ouvrir le formulaire Ajouter un rôle dans l&#39;entreprise.</p><p><strong>Étape : 3</strong> Remplissez les informations suivantes :</p><p><strong>A) Nom –</strong> Saisissez le nom du rôle (par exemple, Administrateur, Gestionnaire, Acheteur).</p><p><strong>B) Description –</strong> Ajoutez une brève description pour préciser l&#39;objectif du rôle.</p><p><strong>Étape : 4</strong> Sous Contrôle d&#39;accès, choisissez le niveau d&#39;accès que vous souhaitez attribuer :</p><p><strong>A) Toutes les autorisations –</strong> Accorde un accès complet à toutes les fonctionnalités disponibles de l&#39;entreprise.</p><p><strong>B) Autorisations personnalisées –</strong> Vous permet de sélectionner manuellement des autorisations spécifiques pour le rôle en fonction des besoins de votre entreprise.</p><p><strong>Étape : 5</strong> Une fois que vous avez configuré les paramètres de contrôle d&#39;accès, cliquez sur Enregistrer le rôle pour créer le nouveau rôle. Comme le montre l&#39;image ci-dessous,</p>",9)),t(s,{src:"/images/b2b-ecommerce-platform/2-add-company-role.png",alt:"Super Admin Login"}),e[2]||(e[2]=r(' <p><strong>Remarque :</strong></p><ul><li><p>Vous pouvez modifier ou supprimer des rôles existants à tout moment à partir de la même page.</p></li><li><p>Une fois un rôle créé, il peut être attribué aux utilisateurs lors de l&#39;ajout ou de la modification d&#39;un utilisateur de l&#39;entreprise.</p></li></ul><h3 id="gestion-des-utilisateurs-de-l-entreprise" tabindex="-1">Gestion des utilisateurs de l&#39;entreprise <a class="header-anchor" href="#gestion-des-utilisateurs-de-l-entreprise" aria-label="Permalink to &quot;Gestion des utilisateurs de l&#39;entreprise&quot;">​</a></h3><p>La fonctionnalité de gestion des utilisateurs de l&#39;entreprise permet aux entreprises d&#39;ajouter et de gérer plusieurs utilisateurs sous leur compte.</p><p>Chaque utilisateur peut avoir un rôle et un niveau d&#39;accès définis, aidant ainsi les entreprises à maintenir un contrôle approprié au sein de leur organisation.</p><h4 id="etapes-pour-ajouter-un-nouvel-utilisateur-d-entreprise" tabindex="-1">Étapes pour ajouter un nouvel utilisateur d&#39;entreprise <a class="header-anchor" href="#etapes-pour-ajouter-un-nouvel-utilisateur-d-entreprise" aria-label="Permalink to &quot;Étapes pour ajouter un nouvel utilisateur d&#39;entreprise&quot;">​</a></h4><p><strong>Étape : 1</strong> Accédez à Mon compte → Profil → Utilisateurs depuis la vitrine de l&#39;entreprise.</p><p><strong>Étape : 2</strong> La page Utilisateurs de l&#39;entreprise apparaîtra, affichant tous les utilisateurs existants avec des options pour les rechercher, les filtrer ou les gérer.</p><p>Comme le montre l&#39;image ci-dessous, la liste apparaîtra initialement vide si aucun utilisateur n&#39;est créé.</p>',10)),t(s,{src:"/images/b2b-ecommerce-platform/3-company-users.png",alt:"Super Admin Login"}),e[3]||(e[3]=r(" <p><strong>Étape : 3</strong> Cliquez sur Ajouter un utilisateur pour ouvrir le formulaire Ajouter un utilisateur d&#39;entreprise.</p><p><strong>Étape : 4</strong> Remplissez les informations suivantes :</p><p><em>A) Prénom –</em> Entrez le prénom de l&#39;utilisateur.</p><p><em>B) Nom de famille –</em> Entrez le nom de famille de l&#39;utilisateur.</p><p><em>C) E-mail –</em> Entrez une adresse e-mail valide.</p><p><em>D) Téléphone –</em> Fournissez le numéro de contact de l’utilisateur.</p><p><em>E) Sexe –</em> Sélectionnez le sexe de l&#39;utilisateur.</p><p><em>F) Date de naissance –</em> Entrez la date de naissance de l&#39;utilisateur.</p><p><em>G) Rôle –</em> Choisissez le rôle approprié dans la liste des rôles créés.</p><p><em>H) Statut –</em> Définissez le compte de l&#39;utilisateur comme Actif ou Inactif.</p><p><em>I) Est suspendu –</em> Si cette option est activée, l&#39;utilisateur peut se connecter mais ne peut pas procéder au paiement. Un message s&#39;affichera : « Votre compte a été suspendu. »</p><p><strong>Étape : 5</strong> Vous pouvez éventuellement télécharger une <strong>image ou une vidéo de profil</strong> pour l&#39;utilisateur.</p><p><strong>Étape : 6</strong> Après avoir rempli toutes les informations requises, cliquez sur <strong>Enregistrer l&#39;utilisateur</strong> pour ajouter le nouvel utilisateur de l&#39;entreprise. Comme le montre l&#39;image ci-dessous.</p>",14)),t(s,{src:"/images/b2b-ecommerce-platform/4-add-company-user.png",alt:"Super Admin Login"}),e[4]||(e[4]=l()),e[5]||(e[5]=i("p",null,[i("strong",null,"Remarque :")],-1)),e[6]||(e[6]=i("p",null,"Les administrateurs de l'entreprise peuvent modifier, suspendre ou supprimer des utilisateurs à tout moment.",-1)),e[7]||(e[7]=i("p",null,"L'accès aux fonctionnalités dépend des autorisations de rôle attribuées à chaque utilisateur.",-1))])}const v=o(p,[["render",m]]);export{A as __pageData,v as default};
